select * from customer;
-- Q1 total revenue generated by male vs female customers?
select gender,sum(purchase_amount) from  customer group by gender order by sum(purchase_amount) desc;

-- Q2 wish customers used a discount but still spend more then the average purchese amount?
select customer_id ,purchase_amount ,(select avg(purchase_amount) from customer) as averag
from customer 
where discount_applied ='Yes' and purchase_amount >(select avg(purchase_amount) as averag from customer);

--  Q3 wich are the top 5 products with the hightest average review rating?

select item_purchased,round(avg(review_rating),2) 
from customer 
group by item_purchased 
order by avg(review_rating) desc limit 5;

-- Q4 Compare the average purchase Amounts between Standard and express shipping 

select shipping_type,round(avg(purchase_amount),2) as avrage from customer 
where shipping_type='Standard' or shipping_type ='Express'
group by shipping_type
order by avg(purchase_amount) desc;

-- Q5 Do subscribed customers spend more ? Compare average spend and total revenue between subscribers and non-subscribers

select subscription_status,
count(customer_id) as total_customers ,
round(avg(purchase_amount),2) as average ,
sum(purchase_amount) as total_purchast 
from customer 
group by subscription_status ;

-- Q6 wish 5 products have the highest percentage  of purchases with discounts applied ?

select item_purchased ,round(100*sum(case when discount_applied='Yes' then 1 else 0 end )/count(*) ,2)as percentage  
from customer
group by item_purchased 
order by percentage  desc
limit 5;

--  Q7 Segment customers into new returning and loyal based on their total number of previous purchases ,and show the count of each segment. 

with cte as (
select  previous_purchases,
case 
when previous_purchases =1 then 'new' 
when previous_purchases between 2 and 10 then 'returning' 
else 'loyal'
end as segments
from customer )
select segments,count(*) as count from cte 
group by segments
;

-- Q8 what are the top 3 most purchased products within each category

with cte as (
select category,item_purchased,count(item_purchased ) as total_count ,row_number() over(partition by category order by count(item_purchased) desc) as rank_num from customer group by category,item_purchased  
) select * from cte where rank_num<4;

-- Q9 are customers who are repeat buyers (more than 5 previows purchases) also likely to subscribe ? 

with cte as ( select previous_purchases,subscription_status as sub from customer where previous_purchases >5)
select sub,count(*) from cte group by  sub ;  
